=Enhance this ad concept for image generation:

Original concept: {{ $json.adConcept }}
Ad type: {{ $json.adType }}
Aspect ratio: {{ $json.aspectRatio }}
Language/market: {{ $json.language }}
Headline: {{ $json.headline }}
Body text: {{ $json.bodyText }}
CTA text: {{ $json.ctaText }}
Product Price: {{ $json.productPrice }}

parameters.jsCode:
// Get enhanced concept from current input
const enhancedConcept = $input.first().json.content || $input.first().json.message?.content || '';

// Set defaults - you'll need to pass these through your workflow
// or change 'Extract Input1' to your actual node name
const variations = $('Extract Input').first().json.variations; // Change this or pass it through
const aspectRatio = '1:1';
const adType = 'with-text';
const adConcept = '';

const styleModifiers = [
  'Professional studio lighting with soft diffused highlights and gentle shadows, ultra-sharp focus, 8K commercial photography quality',
  'Dramatic cinematic lighting with rich contrast and warm golden tones, depth of field effect, premium advertising look',
  'Bright and vibrant natural lighting with clean minimalist aesthetic, high-key photography style, modern and fresh feel',
  'Moody atmospheric lighting with cool blue undertones and selective focus, luxury brand aesthetic, editorial quality',
  'Soft ethereal glow with pastel color grading and dreamy bokeh background, elegant and sophisticated commercial style'
];

const items = [];
for (let i = 0; i < Math.min(variations, 5); i++) {
  const modifier = styleModifiers[i % styleModifiers.length];
  items.push({
    json: {
      variationIndex: i + 1,
      prompt: enhancedConcept + '. ' + modifier,
      enhancedConcept: enhancedConcept,
      originalConcept: adConcept,
      aspect_ratio: aspectRatio,
      resolution: '1K',
      output_format: 'png',
      adType: adType,
      totalVariations: variations
    }
  });
}

return items;

const items = $input.all();

const allDone = items.every(item => {
  const state = item.json.data?.state;
  return state === 'success' || state === 'fail';
});

if (allDone) {
  // All tasks finished - send to output 0 (Aggregate Results)
  return items;
} else {
  // Still processing - we'll use the second output
  // But Code node only has 1 output, so we use a flag
  return items.map(item => ({
    json: {
      ...item.json,
      allDone: allDone
    }
  }));
}

const body = $input.first().json.body;

// Extract and validate selected images
const selectedImages = body.selectedImages || [];
const hasImages = Array.isArray(selectedImages) && selectedImages.length > 0;

return [{
  json: {
    // Basic ad configuration
    adConcept: body.adConcept || '',
    aspectRatio: body.aspectRatio || '1:1',
    adType: body.adType || 'no-text-avatar',
    variations: parseInt(body.variations) || 1,
    resolution: body.resolution || '1K',
    language: body.language || 'en-US',

    // Selected items
    selectedProduct: body.selectedProduct || '',
    selectedBrandId: body.selectedBrandId || '',
    selectedImages: selectedImages,
    selectedTemplate: body.selectedTemplate || 'ai-decide',

    // Image validation flag - USE THIS IN YOUR IF NODE
    hasImages: hasImages,

    // Text content
    headline: body.headline || '',
    bodyText: body.bodyText || '',
    ctaText: body.ctaText || '',
    productPrice: body.productPrice || '',

    // Product data
    productData: body.productData || {},

    // Brand data
    brandData: body.brandData || {},

    // Additional fields
    activeTab: body.activeTab || 'create',
    imageCount: selectedImages.length
  }
}];

